// One-input one-output serial 2's complementer Moore state machine
module TopModule(input  clk, input  areset, input  x, output z);
  reg [15:0] s;
  reg [3:0]  c;
  wire [15:0] s_next;
  wire [3:0]  c_next;
  always @(*) begin
    s_next = {s[14:0], x};
    c_next = c + ({14'b0, x} - s) >> 15;
  end
  always @(posedge clk) begin
    if (areset) begin
      s <= 16'b0;
      c <= 4'b0;
    end else begin
      s <= s_next;
      c <= c_next;
    end
  end
  assign z = ~c;
endmodule

